PROGRAM tank_level
VAR_INPUT
    Level : INT; // Measured tank level in percent
END_VAR
VAR_OUTPUT
    PumpIn : BOOL; // Inlet pump
    ValveOut : BOOL; // Outlet drain valve
END_VAR
VAR
    pumpTimer : TON;
    valveTimer : TON;
    pumpRequest : BOOL := FALSE;
    valveRequest : BOOL := FALSE;
END_VAR

// Call timer instances
pumpTimer(IN := pumpRequest, PT := T#1s);
valveTimer(IN := valveRequest, PT := T#1s);

// Control logic
IF Level <= 10 THEN
    pumpRequest := TRUE;
ELSIF Level >= 90 THEN
    pumpRequest := FALSE;
END_IF;

IF Level >= 90 THEN
    valveRequest := TRUE;
ELSE
    valveRequest := FALSE;
END_IF;

// Assign outputs with safety conditions
IF Level < 90 THEN
    PumpIn := pumpTimer.Q;
ELSE
    PumpIn := FALSE;
END_IF;

ValveOut := valveTimer.Q;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
