END_VAR
VAR_OUTPUT
    PumpIn : BOOL; // Inlet pump
    ValveOut : BOOL; // Outlet drain valve
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpInTimer : TON;
    ValveOutTimer : TON;
END_VAR

// Control logic for PumpIn
IF Level <= LowLimit THEN
    PumpIn := TRUE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF

// Safety condition for PumpIn
IF Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF

// Control logic for ValveOut
IF Level >= HighLimit THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF

END_PROGRAM

