PROGRAM tank_level
VAR_INPUT
    Level : INT; // Measured tank level in percent
END_VAR
VAR_OUTPUT
    PumpIn : BOOL; // Inlet pump
    ValveOut : BOOL; // Outlet drain valve
END_VAR
VAR
    PumpIn_Hysteresis : BOOL := FALSE;
END_VAR

// Implement the control logic
IF Level <= 10 THEN
    PumpIn_Hysteresis := TRUE;
ELSIF Level >= 90 THEN
    PumpIn_Hysteresis := FALSE;
END_IF

// Ensure safety condition: PumpIn must be OFF if Level >= 90
PumpIn := PumpIn_Hysteresis AND (Level < 90);

// Control ValveOut to prevent overflow
ValveOut := (Level >= 90);

END_PROGRAM

