PROGRAM tank_level
VAR_INPUT
    Level : INT;   // Measured tank level in percent
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;   // Inlet pump
    ValveOut : BOOL;   // Outlet drain valve
END_VAR
VAR
    LowLimit : INT := 10;   // Low limit for hysteresis
    HighLimit : INT := 90;  // High limit for hysteresis
END_VAR

// Control logic for the tank level
IF Level <= LowLimit THEN
    PumpIn := TRUE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    IF Level < HighLimit THEN
        ValveOut := FALSE;
    END_IF;
    IF Level > LowLimit THEN
        PumpIn := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL := FALSE;
    DoorB : BOOL := FALSE;
END_VAR
VAR
    TimerA : TON;
    TimerB : TON;
END_VAR

TimerA(IN := OpenA_Cmd AND NOT DoorB, PT := T#1s);
TimerB(IN := OpenB_Cmd AND NOT DoorA AND NOT OpenA_Cmd, PT := T#1s);

