VAR
    State : INT := 0;  (* 0: At-bottom, 1: Moving-up, 2: At-top, 3: Moving-down *)
    UpRequest : BOOL := FALSE;
    DownRequest : BOOL := FALSE;
END_VAR

(* Ensure motors never run together *)
MotorUp := FALSE;
MotorDown := FALSE;

(* State Machine Logic *)
CASE State OF
    0:  (* At-bottom *)
        IF CallUp AND DoorClosed AND NOT AtTop THEN
            State := 1;  (* Transition to Moving-up *)
            UpRequest := TRUE;
        END_IF

    1:  (* Moving-up *)
        IF AtTop THEN
            State := 2;  (* Transition to At-top *)
            UpRequest := FALSE;
        ELSIF NOT DoorClosed THEN
            State := 0;  (* Safety: stop if door opens *)
            UpRequest := FALSE;
        END_IF
        IF UpRequest AND DoorClosed THEN
            MotorUp := TRUE;
        END_IF

    2:  (* At-top *)
        IF CallDown AND DoorClosed AND NOT AtBottom THEN
            State := 3;  (* Transition to Moving-down *)
            DownRequest := TRUE;
        END_IF

    3:  (* Moving-down *)
        IF AtBottom THEN
            State := 0;  (* Transition to At-bottom *)
            DownRequest := FALSE;
        ELSIF NOT DoorClosed THEN
            State := 2;  (* Safety: stop if door opens *)
            DownRequest := FALSE;
        END_IF
        IF DownRequest AND DoorClosed THEN
            MotorDown := TRUE;
        END_IF

ELSE
    State := 0;  (* Default to At-bottom if in invalid state *)
END_CASE
END_PROGRAM

