            FillValve := FALSE;
            IF Level >= LIQ_MIN THEN
                Heater := TRUE;
                Agitator := TRUE;
            ELSE
                Heater := FALSE;
                Agitator := FALSE;
            END_IF;
            DrainValve := FALSE;
            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;
        3:  (* React *)
            FillValve := FALSE;
            IF Level >= LIQ_MIN THEN
                Heater := TRUE;
                Agitator := TRUE;
            ELSE
                Heater := FALSE;
                Agitator := FALSE;
            END_IF;
            DrainValve := FALSE;
            IF ReactTimer.Q THEN
                State := 4;
            END_IF;
        4:  (* Drain *)
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    ELSE
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    END_CASE;
