PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR

VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR

VAR
    Count : INT := 0;
    PrevEntry : BOOL := FALSE;
    PrevExit : BOOL := FALSE;
END_VAR

IF EntrySensor AND NOT PrevEntry THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF
END_IF

IF ExitSensor AND NOT PrevExit THEN
    IF Count > 0 THEN
        Count := Count - 1;
    END_IF
END_IF

FullSign := (Count = 3);
EntryBarrierOpen := (EntryReq AND (Count < 3));

PrevEntry := EntrySensor;
PrevExit := ExitSensor;
END_PROGRAM

PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevEntry : BOOL := FALSE;
    PrevExit : BOOL := FALSE;
END_VAR

VAR CONSTANT
    CAP : INT := 3;
END_VAR

BEGIN
    (* Detect rising edge for EntrySensor *)
    IF EntrySensor AND NOT PrevEntry THEN
        IF Count < CAP THEN
            Count := Count + 1;
        END_IF
    END_IF

    (* Detect rising edge for ExitSensor *)
    IF ExitSensor AND NOT PrevExit THEN
        IF Count > 0 THEN
            Count := Count - 1;
        END_IF
    END_IF

    (* Update previous states *)
    PrevEntry := EntrySensor;
    PrevExit := ExitSensor;

    (* Set FullSign when occupancy is at capacity *)
    IF Count = CAP THEN
        FullSign := TRUE;
    ELSE
        FullSign := FALSE;
    END_IF

    (* Open Entry Barrier only if EntryReq is true and the garage is not full *)
    IF EntryReq AND Count < CAP THEN
        EntryBarrierOpen := TRUE;
    ELSE
        EntryBarrierOpen := FALSE;
    END_IF
END_PROGRAM

