VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR_OUTPUT

VAR
    State : INT := 0; // 0=Idle, 1=Filling, 2=Draining
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF EStop AND StartCycle AND (Level < 90) THEN
            State := 1;
        END_IF

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF (Level >= 90) THEN
            State := 2;
        END_IF

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF (Level <= 10) THEN
            State := 0;
        END_IF
ELSE
    Pump := FALSE;
    Valve := FALSE;
    State := 0;
END_CASE
END_PROGRAM

