        State := 0; // Return to Idle
    END_IF
ELSIF State = 2 THEN // Closing
    MotorOpen := FALSE;
    MotorClose := TRUE;
    IF CloseLimit OR Obstruction OR NOT TON_CLOSE.Q THEN
        State := 0; // Return to Idle
    END_IF
