    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR_OUTPUT

VAR
    State : INT := 0; // 0 = Idle, 1 = Opening, 2 = Closing
END_VAR

IF (MotorOpen AND MotorClose) THEN
    // Safety: Ensure both motors are not energized together
    MotorOpen := FALSE;
    MotorClose := FALSE;
END_IF

CASE State OF
    0: // Idle
        MotorOpen := FALSE;
        MotorClose := FALSE;
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1; // Start Opening
        ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := 2; // Start Closing
        END_IF
    1: // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit THEN
            MotorOpen := FALSE;
            State := 0; // Return to Idle
        END_IF
    2: // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            MotorClose := FALSE;
            State := 0; // Return to Idle
        END_IF
ELSE
    State := 0; // Default to Idle for safety
END_CASE

END_PROGRAM

PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR_OUTPUT

VAR
    State : INT := 0;  // 0=Idle, 1=Opening, 2=Closing
END_VAR

// Ensure motors are not energized together
MotorOpen := FALSE;
MotorClose := FALSE;

// State machine logic
CASE State OF
    0: // Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1; // Start Opening
        ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := 2; // Start Closing
        END_IF

    1: // Opening
        MotorOpen := TRUE;
        IF OpenLimit THEN
            State := 0; // Transition to Idle
        END_IF

    2: // Closing
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            State := 0; // Transition to Idle
        END_IF

ELSE
    State := 0; // Default to Idle in case of unexpected state
END_CASE

END_PROGRAM

