END_IF

CASE State OF
    0: // Idle
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := 2;
        END_IF
    1: // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit THEN
            MotorOpen := FALSE;
            State := 0;
        END_IF
    2: // Closing
        MotorOpen := FALSE;
