PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR
VAR_OUTPUT
    MotorOpen : BOOL := FALSE;
    MotorClose : BOOL := FALSE;
END_VAR
VAR
    State : INT := 0;  // 0=Idle, 1=Opening, 2=Closing
END_VAR

IF State = 0 THEN // Idle
    IF OpenCmd AND NOT OpenLimit THEN
        State := 1; // Transition to Opening
    ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
        State := 2; // Transition to Closing
    END_IF
ELSIF State = 1 THEN // Opening
    MotorOpen := TRUE;
    IF OpenLimit THEN
        MotorOpen := FALSE;
        State := 0; // Transition to Idle
    END_IF
ELSIF State = 2 THEN // Closing
    MotorClose := TRUE;
    IF CloseLimit OR Obstruction THEN
        MotorClose := FALSE;
        State := 0; // Transition to Idle
    END_IF
END_IF

// Ensure both motors are never energized simultaneously
IF MotorOpen THEN
    MotorClose := FALSE;
ELSIF MotorClose THEN
    MotorOpen := FALSE;
END_IF
END_PROGRAM

