Timer2(IN := (State = 2), PT := T#2s);

IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB THEN
    CASE State OF
        0:
            State := 1;
        1:
            IF Timer1.Q THEN
                State := 2;
            END_IF;
        2:
            IF Timer2.Q THEN
                State := 3;
            END_IF;
        3:
            State := 3; // Stay in this state until stop conditions occur
    ELSE
        State := 0;
    END_CASE;
END_IF;

