    StopPB : BOOL;
    EStop : BOOL; // FALSE when activated
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0; // State 0 = Off, 1 = C3, 2 = C3+C2, 3 = all
    Timer1 : TON;
    Timer2 : TON;
END_VAR

Timer1(IN := (State = 1), PT := T#2s);
Timer2(IN := (State = 2), PT := T#2s);

IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB AND State = 0 THEN
    State := 1;
END_IF

CASE State OF
    0: // All conveyors off
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1: // Start C3
        C3 := TRUE;
        C2 := FALSE;
        C1 := FALSE;
        IF Timer1.Q THEN
            State := 2;
        END_IF
    2: // Start C3 and C2
        C3 := TRUE;
        C2 := TRUE;
        C1 := FALSE;
        IF Timer2.Q THEN
            State := 3;
        END_IF
    3: // Start all conveyors
        C3 := TRUE;
        C2 := TRUE;
        C1 := TRUE;
END_CASE
END_PROGRAM

